function* unfold<S, A>(seed: S, step: (s: S) => readonly [A, S] | null): Generator<A> {
  let s = seed;
  for (let r = step(s); r !== null; r = step(s)) {
    yield r[0];                       // one layer per next()
    s = r[1];                         // next seed
  }
}
// [...unfold(3, n => (n > 0 ? ([n, n - 1] as const) : null))]  ->  [3, 2, 1]
